CREATE Proc [dbo].[ReportDsnoWiseIssuanceReport] @DSNoId as nvarchar(50), @Login as nvarchar(max) as select @Login as LoginUser,ism.Date,ism.IssNo,s.Store,Un.Unit as Branch,c.Category,sc.Subcategory,i.Item, U.Unit as PackingType, iu.PurFactor as UnitQty,db.DSNo,(Select Distinct(Unit) from unit  where UId=issd.Unit) as UnitType, issd.Qty as IssuedQty,  ( Cast (isnull(Round([dbo].uspGetItemAvgRateFunc(s.SId,i.ItemId,null,null,0),2),0)AS DECIMAL (18,2))  ) as UnitPrice from IssuanceMaster_Store ism  inner join IssuanceDetail_Store issd on ism.IssId=issd.IssId inner join Branch b on ism.BRId=b.BRId inner join DemandSheetMaster_Branch db on ism.BRId=b.BRId inner join Store s on ism.SId=s.SId inner join Item i on issd.ItemId=i.ItemId inner join Subcategory sc on i.SBId = sc.SBId inner join Category c on sc.CId=c.CId inner join ItemUnit iu on i.ItemId=iu.ItemId inner join Unit U on iu.PkUnit=U.UId inner join Unit Un on iu.PurUnit=Un.UId inner join Split(@DSNoId,',') sp on sp.items =ism.DSId where ism.DSId=db.DSId group by ism.Date,ism.IssNo,Un.Unit,c.Category,sc.Subcategory,i.Item, U.Unit,iu.PurFactor,db.DSNo,issd.Unit,issd.Qty,i.ItemId,s.Store,s.SId order by ism.date asc